func TestGetData(t *testing.T) {
	data, err := GetCode("https://github.com/aergoio/ARC2NFT/raw/master/src/ARC2-Mintable.lua")
	require.NoError(t, err)
	require.Greater(t, len(data), 0, "data should have length > 0")
}

