func TestGetDataAndCompile(t *testing.T) {
	coreCode, err := GetCode("https://github.com/aergoio/ARC2NFT/raw/master/src/ARC2-Core.lua")
	require.NoError(t, err)
	mintableCode, err := GetCode("https://github.com/aergoio/ARC2NFT/raw/master/src/ARC2-Mintable.lua")
	require.NoError(t, err)
	code := coreCode + mintableCode
	// Compile the code
	byteCodeABI, err := CompileCode(code)
	require.NoError(t, err)
	require.Equal(t, 10061, len(byteCodeABI), "compiled ARC2 bytecode should have length 10061 bytes")
	require.Equal(t, []byte{0x90, 0x20, 0x0, 0x0, 0x1b, 0x4c, 0x4a, 0x2, 0xa, 0x8b, 0x7, 0x0, 0x2, 0xb, 0x0, 0x18, 0x1, 0x8a}, byteCodeABI[:18], "bytecode should start with expected bytes")
}

// utility function for tests
func readLuaCode(file string) (luaCode string) {
	_, filename, _, ok := runtime.Caller(0)
	if ok != true {
		return ""
	}
	raw, err := os.ReadFile(filepath.Join(filepath.Dir(filename), "test_files", file))
	if err != nil {
		return ""
	}
	return string(raw)
}
